import React, { useState, useRef } from 'react';
import FMCSADailyLogSheet from './FMCSADailyLogSheet';

/**
 * DailyLogPlaceholder component managing multi-day FMCSA Driver Daily Log sheets.
 * Includes an icon-only PDF download feature using html2pdf.js targeting a dedicated
 * multi-page printable ref (driverLogRef).
 *
 * @param {Object} props
 * @param {Array} props.logs - Array of daily log objects generated by backend
 * @param {Array} props.dailyLogs - Alternative prop alias for daily logs array
 * @param {Boolean} props.isLoading - Skeleton loader indicator
 */
const DailyLogPlaceholder = ({ logs, dailyLogs, isLoading = false }) => {
  const [selectedDayIdx, setSelectedDayIdx] = useState(0);
  const [isExporting, setIsExporting] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');

  const driverLogRef = useRef(null);

  const actualLogs = dailyLogs || logs || [];
  const hasLogs = Array.isArray(actualLogs) && actualLogs.length > 0;
  const totalSheets = hasLogs ? actualLogs.length : 0;
  const currentLog = hasLogs ? actualLogs[selectedDayIdx] || actualLogs[0] : null;

  const handlePrev = () => {
    if (selectedDayIdx > 0) {
      setSelectedDayIdx((prev) => prev - 1);
    }
  };

  const handleNext = () => {
    if (selectedDayIdx < totalSheets - 1) {
      setSelectedDayIdx((prev) => prev + 1);
    }
  };

  /**
   * Handles exporting ONLY the Driver Daily Log Sheets to a multi-page PDF document
   */
  const handleDownloadLogs = async () => {
    if (!hasLogs) {
      setErrorMessage('Generate a trip plan before downloading logs.');
      setTimeout(() => setErrorMessage(''), 3500);
      return;
    }

    if (!driverLogRef.current) return;

    setIsExporting(true);
    setErrorMessage('');

    try {
      const html2pdf = (await import('html2pdf.js')).default;
      const element = driverLogRef.current;

      const opt = {
        margin: [6, 6, 6, 6],
        filename: `FMCSA_Driver_Daily_Logs_${new Date().toISOString().split('T')[0]}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: {
          scale: 2,
          useCORS: true,
          logging: false,
          letterRendering: true,
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['css', 'legacy'] },
      };

      await html2pdf().set(opt).from(element).save();
    } catch (err) {
      console.error('PDF Export error, falling back to window.print():', err);
      window.print();
    } finally {
      setIsExporting(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Off-screen Multi-Page Ref Container for PDF Export */}
      {hasLogs && (
        <div style={{ position: 'absolute', left: '-9999px', top: '-9999px', width: '800px' }}>
          <div ref={driverLogRef} className="space-y-8 bg-white p-4 text-black">
            {actualLogs.map((logItem, idx) => (
              <div key={idx} style={{ pageBreakAfter: 'always', breakAfter: 'page' }}>
                <FMCSADailyLogSheet log={logItem} />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Header bar */}
      <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-6 shadow-2xl backdrop-blur-md">
        <div className="flex items-center justify-between pb-4 border-b border-slate-800">
          <div>
            <h3 className="text-xl font-bold text-slate-100 flex items-center space-x-2">
              <svg className="w-5 h-5 text-indigo-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
              <span>FMCSA Driver Daily Log Sheets</span>
            </h3>
            <p className="text-xs text-slate-400 mt-1">Official 24-hour driver log sheets with vector duty status graph</p>
          </div>

          {/* Top-Right Corner Icon-Only Download Button */}
          <div className="flex items-center space-x-3">
            <span className={`hidden sm:inline-block text-xs font-mono px-3 py-1.5 rounded-xl border ${hasLogs ? 'bg-emerald-950 text-emerald-300 border-emerald-800' : 'bg-slate-800 text-slate-500 border-slate-700'}`}>
              {isLoading ? 'Generating Logs...' : hasLogs ? `${totalSheets} Log Sheet(s)` : 'Awaiting Trip Plan'}
            </span>

            {/* Clean Download Icon Button */}
            <button
              type="button"
              onClick={handleDownloadLogs}
              disabled={!hasLogs || isExporting}
              aria-label="Download Driver Daily Logs"
              title={hasLogs ? 'Download Driver Daily Logs' : 'Generate a trip plan before downloading logs.'}
              className={`p-2.5 rounded-xl border transition-all duration-200 cursor-pointer flex items-center justify-center group ${
                hasLogs
                  ? 'bg-slate-800 hover:bg-indigo-600 border-slate-700 hover:border-indigo-500 text-slate-200 hover:text-white shadow-md hover:scale-110'
                  : 'bg-slate-900 border-slate-800 text-slate-600 cursor-not-allowed opacity-50'
              }`}
            >
              {isExporting ? (
                <svg className="animate-spin w-5 h-5 text-indigo-400" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
              ) : (
                <svg className="w-5 h-5 transition-transform duration-200 group-hover:translate-y-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
                </svg>
              )}
            </button>
          </div>
        </div>

        {/* Error Notification Toast if user attempts download without trip plan */}
        {errorMessage && (
          <div className="mt-3 p-3 bg-amber-950/80 border border-amber-800 text-amber-300 text-xs font-mono rounded-xl flex items-center space-x-2">
            <svg className="w-4 h-4 shrink-0 text-amber-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
            <span>{errorMessage}</span>
          </div>
        )}

        {isLoading ? (
          /* Skeleton Loader */
          <div className="py-8 space-y-4 animate-pulse mt-6">
            <div className="h-10 bg-slate-800/60 rounded-xl w-full"></div>
            <div className="h-64 bg-slate-800/40 rounded-2xl border border-slate-800 w-full"></div>
            <div className="h-24 bg-slate-800/30 rounded-xl w-full"></div>
          </div>
        ) : !hasLogs ? (
          /* Empty State */
          <div className="py-12 text-center bg-slate-950/60 rounded-xl border border-slate-800/80 mt-6">
            <svg className="w-10 h-10 text-slate-600 mx-auto mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
            </svg>
            <p className="text-sm font-semibold text-slate-300">No Driver Daily Logs Available</p>
            <p className="text-xs text-slate-500 mt-1">Submit the trip planner form to generate official FMCSA daily log sheets.</p>
          </div>
        ) : (
          /* Log Sheet View */
          <div className="mt-6 space-y-6">
            {/* Paginated Navigation Bar */}
            <div className="no-print flex flex-col sm:flex-row sm:items-center justify-between gap-3 bg-slate-950/90 p-3 rounded-xl border border-slate-800">
              {/* Previous Button */}
              <button
                type="button"
                onClick={handlePrev}
                disabled={selectedDayIdx === 0}
                className={`px-4 py-2 rounded-xl text-xs font-mono font-bold transition flex items-center space-x-1.5 ${
                  selectedDayIdx === 0
                    ? 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'
                    : 'bg-slate-800 hover:bg-indigo-600 text-slate-200 hover:text-white border border-slate-700 shadow-md'
                }`}
              >
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                </svg>
                <span>Previous Sheet</span>
              </button>

              {/* Page Indicator Badge */}
              <div className="text-center font-mono text-xs">
                <span className="text-slate-400">Sheet </span>
                <span className="font-bold text-indigo-400">{selectedDayIdx + 1}</span>
                <span className="text-slate-400"> of </span>
                <span className="font-bold text-slate-200">{totalSheets}</span>
                <span className="text-slate-500 font-semibold ml-2">
                  (Day #{currentLog?.day_number} — {currentLog?.date})
                </span>
              </div>

              {/* Next Button */}
              <button
                type="button"
                onClick={handleNext}
                disabled={selectedDayIdx >= totalSheets - 1}
                className={`px-4 py-2 rounded-xl text-xs font-mono font-bold transition flex items-center space-x-1.5 ${
                  selectedDayIdx >= totalSheets - 1
                    ? 'bg-slate-900 text-slate-600 border border-slate-800 cursor-not-allowed'
                    : 'bg-slate-800 hover:bg-indigo-600 text-slate-200 hover:text-white border border-slate-700 shadow-md'
                }`}
              >
                <span>Next Sheet</span>
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                </svg>
              </button>
            </div>

            {/* Quick Day Tab Shortcuts */}
            {totalSheets > 1 && (
              <div className="no-print flex items-center space-x-2 overflow-x-auto pb-1">
                <span className="text-xs font-mono uppercase text-slate-400 mr-1 shrink-0">Quick Jump:</span>
                {actualLogs.map((logItem, idx) => (
                  <button
                    key={idx}
                    type="button"
                    onClick={() => setSelectedDayIdx(idx)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-mono font-semibold transition shrink-0 ${
                      selectedDayIdx === idx
                        ? 'bg-indigo-950 text-indigo-300 border border-indigo-700'
                        : 'bg-slate-900/60 text-slate-400 hover:text-slate-200 border border-slate-800'
                    }`}
                  >
                    Day {logItem.day_number || idx + 1}
                  </button>
                ))}
              </div>
            )}

            {/* Active FMCSA Paper Log Sheet View */}
            {currentLog && (
              <div className="print-only-log">
                <FMCSADailyLogSheet log={currentLog} />
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default DailyLogPlaceholder;
